function weatherDestination(city, country, lat, lon, device) {
  if (
    typeof city !== "string" ||
    !city.trim() ||
    typeof country !== "string" ||
    !/^[A-Z]{2}$/.test(country) ||
    !Number.isFinite(lat) ||
    Math.abs(lat) > 90 ||
    !Number.isFinite(lon) ||
    Math.abs(lon) > 180
  ) {
    throw new Error(
      "Set one city, its two-letter country code, and decimal latitude and longitude",
    );
  }
  if (
    typeof device !== "string" ||
    !/^[A-Za-z0-9_-]{1,25}$/.test(device) ||
    device === "YOUR_DEVICE_NAME"
  ) {
    throw new Error("Set one named Pushover device");
  }
  return { city: city.trim(), country, lat, lon, device };
}

const { city, country, lat, lon, device } = {
  city: "Berlin",
  country: "DE",
  lat: 52.52,
  lon: 13.405,
  device: "YOUR_DEVICE_NAME",
};
return { json: weatherDestination(city, country, lat, lon, device) };

function celsiusReading(data, place) {
  const degrees = data?.main?.temp;
  const coords = data?.coord;
  if (String(data?.cod) !== "200" || !Number.isFinite(degrees)) {
    throw new Error("OpenWeather did not return a current numerical temperature");
  }
  function normalizeCity(value) {
    return typeof value === "string" ? value.normalize("NFKC").trim().toLowerCase() : "";
  }
  if (
    data.sys?.country !== place.country ||
    normalizeCity(data.name) !== normalizeCity(place.city) ||
    !Number.isFinite(coords?.lat) ||
    !Number.isFinite(coords?.lon) ||
    Math.abs(coords.lat - place.lat) > 0.005 ||
    Math.abs(coords.lon - place.lon) > 0.005
  ) {
    throw new Error("OpenWeather did not confirm the configured city and coordinates");
  }
  return {
    device: place.device,
    title: "Today's Weather Update",
    message: "Hey! The temperature outside is " + degrees + "°C.",
  };
}

const place = $("Set the city and device").first().json;
return { json: celsiusReading($json, place) };

function checkDevice(result, device) {
  if (result?.status !== 1 || !Array.isArray(result.devices) || !result.devices.includes(device)) {
    throw new Error("Pushover did not confirm that the configured device is active for this user");
  }
}

const notification = $("Check location and temperature").first().json;
checkDevice($json, notification.device);
return { json: { ...notification, priority: 0 } };

function checkPush(result) {
  if (result?.status !== 1 || typeof result.request !== "string" || !result.request.trim()) {
    throw new Error("Pushover did not confirm the notification");
  }
  return result.request;
}

return { json: { requestId: checkPush($json) } };
